/*
 * AirPods pictures, in the active theme's look (ui/theme.h): a small glyph
 * for the status bar and the HUD (ui/hud.h), and the buds and the charging
 * case for the battery card (ui/airpods_notify.h).
 *
 *   - Glass: photos of AirPods Pro and their case, and MingCute's AirPods
 *     icon for the glyph -- freely licensed (credits in airpods_art_data.c),
 *     generated by tools/airpods-art.py.
 *   - Classic: pixel art in the manner of the iPod's own bitmaps, drawn at
 *     its pixel size (RPOD_CLASSIC_PX) in the theme's text colour.
 *
 * The descriptors never move -- an lv_image only keeps a pointer to its
 * source. Call these again after a theme change.
 */

#ifndef RPOD_AIRPODS_ART_H
#define RPOD_AIRPODS_ART_H

#include "lvgl.h"

#include <stdbool.h>

/* A pair of AirPods as an A8 mask, for the status bar -- or, `small`, for
 * the HUD, whose classic box is too short for the title bar's size (in
 * Glass they're one size). NULL if out of memory. */
const lv_image_dsc_t *rpod_airpods_glyph(bool small);

/* The pair of buds, and the case with its lid shut. NULL if out of memory. */
const lv_image_dsc_t *rpod_airpods_art_buds(void);
const lv_image_dsc_t *rpod_airpods_art_case(void);

/* An lv_image of one of the above (or of nothing, for NULL): a mask is drawn
 * in `color`, a photo as it is. Recolour a mask later with
 * lv_obj_set_style_image_recolor(). */
lv_obj_t *rpod_airpods_image_create(lv_obj_t *parent, const lv_image_dsc_t *dsc, lv_color_t color);

#endif /* RPOD_AIRPODS_ART_H */
